<template>
  <div class="mobile-video-uploader" :class="{'mobile-video-uploader-video': fileList.length > 0}">
    <!-- 上传成功后的视频回显 -->
    <div v-if="currentUploadResult" class="video-preview-container">
      <MobileLVideo
        ref="videoRef"
        :src="currentUploadResult.url"
        w="100%"
        h="100%"
        :show-controls="false"
        :autoplay="true"
        :muted="true"
        :loop="true"
        @play="handleVideoPlay"
        @pause="handleVideoPause"
        class="video-preview"
      />
      
      <!-- 自定义控制层 -->
      <div class="video-control-overlay">
        <!-- 右上角播放/暂停按钮 -->
        <div class="top-right-controls">
          <button 
            class="play-pause-btn"
            @click="togglePlayPause"
          >
            <MobileLImg 
              v-show="!isVideoPlaying" 
              src="/static/mobile_images/pause_icon.png" 
              w="16px" 
              h="16px"
              class="control-icon"
            />
            <MobileLImg 
              v-show="isVideoPlaying" 
              src="/static/mobile_images/play_icon.png" 
              w="16px" 
              h="16px"
              class="control-icon"
            />
          </button>
        </div>

         <!-- Change/Delete操作覆盖层 - 仅在有视频时显示 -->
         <div class="video-actions" v-if="currentUploadResult">
              <div class="action-change" @click="handleChangeVideo">
                <span class="action-text">{{ t('change') }}</span>
              </div>
              <div class="action-divider"></div>
              <div class="action-delete" @click="handleDeleteVideo">
                <span class="action-text">{{ t('delete') }}</span>
              </div>
            </div>
      </div>
    </div>
    
    <!-- 上传区域 -->
    <van-uploader
      v-else
      v-model="fileList"
      :max-count="1"
      :max-size="maxSize"
      :accept="accept"
      :before-read="beforeRead"
      :after-read="afterRead"
      :before-delete="beforeDelete"
      :preview-size="['100%', '100%']"
      upload-text="Upload video file"
      preview-cover
      @oversize="onOversize"
      @delete="onDelete"
      image-fit="contain"
    >
      <template #preview-cover="{ file }">
        <div class="upload-preview-cover" v-if="file.status === 'uploading'">
          <div class="upload-progress">
            <van-loading type="spinner" color="#2563EB" size="20px" />
            <span class="upload-text">Uploading...</span>
          </div>
        </div>
        <div class="upload-preview-cover" v-else-if="file.status === 'failed'">
          <div class="upload-error">
            <span class="error-icon">❌</span>
            <span class="error-text">Upload Failed</span>
          </div>
        </div>
      </template>
    </van-uploader>
  </div>
</template>

<script setup>
// 引入区域
import { ref, computed } from 'vue';
import { useI18n } from 'vue-i18n';
import { showToast } from 'vant';
import MobileLVideo from '@/mobile/components/mobile-l-video.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';

// props区域
const props = defineProps({
  maxSize: {
    type: Number,
    default: 50 * 1024 * 1024 // 50MB
  },
  accept: {
    type: String,
    default: 'video/mp4,video/avi,video/mov,video/wmv,video/flv,video/webm'
  }
});

// emits区域
const emit = defineEmits(['onUploadSuccess', 'onUploadRemove']);

// 变量区域
const { t } = useI18n();

// 响应式变量
const fileList = ref([]);
const currentUploadResult = ref(null);
const isVideoPlaying = ref(false);
const videoRef = ref(null);

// 计算属性区域
const maxSizeMB = computed(() => {
  return Math.round(props.maxSize / 1024 / 1024);
});

// 自定义事件区域
const beforeRead = (file) => {
  // 如果已有视频，先清除
  if (fileList.value.length > 0) {
    fileList.value = [];
    currentUploadResult.value = null;
    // 通知父组件已移除之前的视频
    emit('onUploadRemove');
  }

  // 验证文件类型
  const allowedTypes = [
    'video/mp4',
    'video/avi', 
    'video/mov',
    'video/wmv',
    'video/flv',
    'video/webm',
    'video/quicktime'
  ];
  if (!allowedTypes.includes(file.type)) {
    showToast(t('fileTypeNotAllowed'));
    return false;
  }

  // 验证文件大小
  if (file.size > props.maxSize) {
    showToast(`${t('fileSizeExceedsLimit')} ${maxSizeMB.value}MB`);
    return false;
  }

  return true;
};

const afterRead = async (file) => {
  try {
    // 设置上传状态
    file.status = 'uploading';
    file.message = 'Uploading...';

    // 创建视频预览URL
    const videoUrl = URL.createObjectURL(file.file);
    
    // 模拟上传过程（实际项目中会调用真实的视频上传API）
    await new Promise(resolve => setTimeout(resolve, 1500));
    
    // 上传成功
    file.status = 'done';
    currentUploadResult.value = {
      url: videoUrl,
      originalFile: file.file,
      fileName: file.file.name,
      fileSize: file.file.size
    };

    // 清空文件列表，触发模板重新渲染显示视频预览
    fileList.value = [];

    // 自动播放视频
    setTimeout(() => {
      if (videoRef.value) {
        videoRef.value.play();
        isVideoPlaying.value = true;
      }
    }, 200);

    // 通知父组件
    emit('onUploadSuccess', currentUploadResult.value);

  } catch (error) {
    console.error('Video upload failed:', error);
    
    // 上传失败
    file.status = 'failed';
    file.message = 'Upload failed';
    
    showToast(t('uploadFailed'));
  }
};

const beforeDelete = (file, detail) => {
  return new Promise((resolve) => {
    // 可以在这里添加删除确认逻辑
    resolve(true);
  });
};

const onOversize = (file) => {
  showToast(`${t('fileSizeExceedsLimit')} ${maxSizeMB.value}MB`);
};

const onDelete = (file, detail) => {
  console.log('File deleted:', file);
  
  // 清理上传结果
  if (currentUploadResult.value && currentUploadResult.value.url) {
    URL.revokeObjectURL(currentUploadResult.value.url);
  }
  currentUploadResult.value = null;
  isVideoPlaying.value = false;
  
  // 通知父组件
  emit('onUploadRemove');
};

// 业务逻辑区域
const togglePlayPause = () => {
  if (videoRef.value) {
    if (isVideoPlaying.value) {
      videoRef.value.pause();
    } else {
      videoRef.value.play();
    }
    isVideoPlaying.value = !isVideoPlaying.value;
  }
};

const handleVideoPlay = () => {
  isVideoPlaying.value = true;
};

const handleVideoPause = () => {
  isVideoPlaying.value = false;
};

const handleChangeVideo = () => {
  // 触发文件选择，重新上传
  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = props.accept;
  fileInput.onchange = (event) => {
    const file = event.target.files[0];
    if (file) {
      // 先清理当前视频
      handleDeleteVideo();
      // 模拟文件上传流程
      const fakeFile = { file };
      if (beforeRead(fakeFile)) {
        afterRead(fakeFile);
      }
    }
  };
  fileInput.click();
};

const handleDeleteVideo = () => {
  // 清理上传结果
  if (currentUploadResult.value && currentUploadResult.value.url) {
    URL.revokeObjectURL(currentUploadResult.value.url);
  }
  currentUploadResult.value = null;
  isVideoPlaying.value = false;
  
  // 通知父组件
  emit('onUploadRemove');
};

// 导出区域
defineExpose({
  reset: () => {
    if (currentUploadResult.value && currentUploadResult.value.url) {
      URL.revokeObjectURL(currentUploadResult.value.url);
    }
    fileList.value = [];
    currentUploadResult.value = null;
    isVideoPlaying.value = false;
  },
  getCurrentVideo: () => {
    return currentUploadResult.value;
  },
  togglePlayPause
});
</script>

